// ── Normalize Place ───────────────────────────────────────────────
// Merapikan output Serper /places jadi bentuk yang konsisten.
// Node ini TIDAK memanggil internet. Cuma bersih-bersih data.

const params = $('Set Search Params').first().json;

function toE164ID(raw) {
  if (!raw) return '';
  let d = String(raw).replace(/[^\d+]/g, '');
  if (d.startsWith('+62')) d = d.slice(1);
  else if (d.startsWith('62')) { /* sudah benar */ }
  else if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (d.startsWith('8')) d = '62' + d;
  else return '';
  d = d.replace(/\D/g, '');
  if (!/^62\d{8,13}$/.test(d)) return '';
  return '+' + d;
}

function originOf(url) {
  try { return new URL(String(url)).origin; } catch (e) { return ''; }
}

function domainOf(url) {
  try { return new URL(String(url)).hostname.replace(/^www\./i, '').toLowerCase(); }
  catch (e) { return ''; }
}

// example.invalid dijamin gagal resolve (RFC 2606) -> ditangkap onError,
// jadi item tetap keluar 1:1 dan urutan tidak bergeser.
const DEAD = 'https://no-website.invalid';

return $input.all().map((item, i) => {
  const p = item.json || {};
  const website = p.website || '';
  const origin = originOf(website);
  const domain = domainOf(website);
  const telepon = toE164ID(p.phoneNumber);

  return {
    json: {
      nama_bisnis: p.title || '',
      kategori: p.category || '',
      alamat: p.address || '',
      kota: params.lokasi || '',
      website: website,
      domain: domain,
      origin: origin,
      telepon_gmaps: telepon,
      is_mobile: /^\+628/.test(telepon),
      rating: p.rating != null ? p.rating : '',
      jumlah_review: p.ratingCount != null ? p.ratingCount : '',
      maps_cid: p.cid || '',
      dedupe_key: domain || telepon || String(p.title || '').toLowerCase().trim(),
      // URL untuk 2 node fetch berikutnya
      url_home: origin || DEAD,
      url_contact: origin ? origin + '/contact' : DEAD,
    },
    pairedItem: i,
  };
});

// ── Extract Contacts ──────────────────────────────────────────────
// Gabungkan metadata Google Maps + HTML homepage + HTML halaman kontak.
// Pakai index (bukan Merge node) karena setiap node fetch di-set
// onError=continueRegularOutput, jadi jumlah item selalu 1:1 dan urut.

const meta = $('Normalize Place').all();
const home = $('Fetch Website').all();
const items = $input.all(); // output Fetch Contact Page

const NOISE_LOCAL = /^(no-?reply|donotreply|postmaster|abuse|webmaster|mailer-daemon|privacy|dpo|example|your|email|name|user|username|sentry|wix|u003)/i;
const NOISE_DOMAIN = /(sentry\.io|wixpress|godaddy|squarespace|shopify|example\.(com|org|net)|yourdomain|yoursite|domain\.com|email\.com|sample\.com|test\.com|\.png|\.jpe?g|\.gif|\.svg|\.webp|\.css|\.js|\.woff)/i;

function toText(h) {
  return String(h || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&#0?64;|&commat;/gi, '@')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ');
}

function normPhone(raw) {
  let d = String(raw).replace(/\D/g, '');
  if (d.startsWith('62')) { /* ok */ }
  else if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (d.startsWith('8')) d = '62' + d;
  else return '';
  if (!/^628\d{7,12}$/.test(d)) return '';
  return '+' + d;
}

function grabEmails(rawHtml) {
  const raw = String(rawHtml || '');
  const found = new Set();

  // 1. mailto: -> presisi paling tinggi
  const mailtos = raw.match(/mailto:([^"'?>\s\\]+)/gi) || [];
  for (const m of mailtos) {
    try { found.add(decodeURIComponent(m.replace(/^mailto:/i, ''))); } catch (e) { /* skip */ }
  }

  // 2. teks polos (HTML sudah di-strip dulu, kalau tidak akan kena URL aset)
  const plain = toText(raw).match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
  for (const m of plain) found.add(m);

  const valid = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
  return [...found]
    .map(function (e) { return e.trim().toLowerCase().replace(/[.,;:)\]]+$/, ''); })
    .filter(function (e) {
      if (!valid.test(e)) return false;
      if (NOISE_DOMAIN.test(e)) return false;
      if (NOISE_LOCAL.test(e.split('@')[0])) return false;
      return true;
    });
}

function grabPhones(rawHtml) {
  const text = toText(rawHtml).replace(/[\u2010-\u2015\u00A0]/g, '-');
  const re = /(?:\+?62|0)[\s.\-]?8\d{1,3}(?:[\s.\-]?\d{2,4}){2,4}/g;
  const out = new Set();
  const hits = text.match(re) || [];
  for (const h of hits) {
    const n = normPhone(h);
    if (n) out.add(n);
  }
  return [...out];
}

function pickEmail(emails, domain) {
  if (!emails.length) return '';
  function score(e) {
    const parts = e.split('@');
    const local = parts[0];
    const dom = parts[1] || '';
    let s = 0;
    if (domain && dom === domain) s += 100;
    if (domain && dom.endsWith('.' + domain)) s += 80;
    if (/^(sales|marketing|info|contact|kontak|cs|customer|order|halo|hello|admin)/.test(local)) s += 20;
    if (/(gmail|yahoo|hotmail|outlook|icloud)\./.test(dom)) s -= 15;
    if (local.length > 30) s -= 10;
    return s;
  }
  return emails.slice().sort(function (a, b) { return score(b) - score(a); })[0];
}

const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
const seen = new Set();
const results = [];

for (let i = 0; i < items.length; i++) {
  const m = (meta[i] && meta[i].json) || {};
  const h1 = (home[i] && home[i].json && home[i].json.data) || '';
  const h2 = (items[i] && items[i].json && items[i].json.data) || '';
  const blob = String(h1) + ' ' + String(h2);

  const emails = grabEmails(blob);
  const phones = grabPhones(blob);

  const email = pickEmail(emails, m.domain);
  const telepon = m.telepon_gmaps || phones[0] || '';
  const whatsapp = m.is_mobile ? m.telepon_gmaps : (phones[0] || '');

  // Buang yang tidak punya jalur kontak sama sekali - itu bukan lead.
  if (!email && !telepon && !m.website) continue;

  // Dedupe dalam satu run
  const key = m.dedupe_key || String(m.nama_bisnis || '').toLowerCase();
  if (!key || seen.has(key)) continue;
  seen.add(key);

  results.push({
    json: {
      'Nama Bisnis': m.nama_bisnis || '',
      'Kategori': m.kategori || '',
      'Alamat': m.alamat || '',
      'Kota': m.kota || '',
      'Website': m.website || '',
      'Email': email,
      'Email Lain': emails.filter(function (e) { return e !== email; }).slice(0, 3).join('; '),
      'No. Telepon': telepon,
      'WhatsApp': whatsapp,
      'Rating': m.rating,
      'Jumlah Review': m.jumlah_review,
      'Sumber': 'Google Maps via Serper',
      'Tanggal Ambil': now,
      maps_cid: m.maps_cid || '',
      dedupe_key: key,
    },
    pairedItem: i,
  });
}

return results;

// ── Build SORA Payload ───────────────────────────────────────────────────────
// Maps the sheet-shaped output of Extract Contacts onto the API contract in
// docs/SPEC.md §2, then signs it.
//
// Sheet headers ("Nama Bisnis") are a presentation format. The API speaks one
// canonical shape so that n8n, CSV upload and anything added later all land in
// the same pipeline.

// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto, which docker-compose.n8n.yml sets.
const crypto = require('crypto');

const config = $('SORA Config').first().json;
const SECRET = config.webhook_secret;
const CAMPAIGN_ID = config.campaign_id;

if (!SECRET) throw new Error('SORA Config: webhook_secret is empty — is SORA_WEBHOOK_SECRET set on the container?');
if (!CAMPAIGN_ID) throw new Error('SORA Config: campaign_id is empty — run `pnpm campaign:create` and set SORA_CAMPAIGN_ID');

function clean(value) {
  const s = String(value ?? '').trim();
  return s === '' ? null : s;
}

const items = $input.all().map((item) => {
  const j = item.json || {};

  // Google Maps provenance, so "where did this lead come from" stays answerable.
  const cid = clean(j.maps_cid);
  const sourceUrl = cid ? `https://www.google.com/maps?cid=${cid}` : clean(j.Website);

  return {
    company_name: String(j['Nama Bisnis'] ?? '').trim(),
    category: clean(j['Kategori']),
    address: clean(j['Alamat']),
    city: clean(j['Kota']),
    website: clean(j['Website']),
    email: clean(j['Email']),
    phone: clean(j['No. Telepon']),
    whatsapp: clean(j['WhatsApp']),
    source_url: sourceUrl,
    // Everything else rides along untouched, for debugging and re-processing.
    raw: j,
  };
});

// One key per run, computed once. A retry of THIS run must reuse it — that is
// what makes a redelivery insert nothing. A new search gets a new key.
const params = $('Set Search Params').first().json;
const stamp = new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
const slug = `${params.keyword}-${params.lokasi}-p${params.page ?? 1}`.toLowerCase().replace(/[^a-z0-9]+/g, '-');
const idempotencyKey = `run_${slug}_${stamp}`;

const payload = {
  campaign_id: CAMPAIGN_ID,
  source: 'serper_places',
  idempotency_key: idempotencyKey,
  items,
};

// Sign the string that will actually be sent, and send this exact string.
const body = JSON.stringify(payload);
const signature =
  'sha256=' + crypto.createHmac('sha256', SECRET).update(body, 'utf8').digest('hex');

return [{ json: { body, signature, item_count: items.length, idempotency_key: idempotencyKey } }];

// ── Search Plan ──────────────────────────────────────────────────────────────
// The only place you edit for a bigger sweep. One Execute runs every
// combination below, one search at a time, and each lands in SORA separately.
//
// Serper /places returns at most 20 per request, so PAGES is how you go past 20
// for a single city: [1, 2, 3] gives up to 60.

const KEYWORDS = ['pet shop'];
const KOTA     = ['Surabaya'];
const PAGES    = [1];

const JUMLAH = 20;   // per request; 20 is the Serper /places ceiling
const NEGARA = 'id';

const plan = [];
for (const keyword of KEYWORDS) {
  for (const lokasi of KOTA) {
    for (const page of PAGES) {
      plan.push({ json: { keyword, lokasi, page, jumlah: JUMLAH, negara: NEGARA } });
    }
  }
}

if (plan.length === 0) throw new Error('Search Plan is empty — fill KEYWORDS and KOTA');

// One Serper request per item, plus up to two page fetches per business found.
// 12 combinations is a few minutes, not seconds.
return plan;

// ── Run Summary ──────────────────────────────────────────────────────────────
// The loop's "done" output carries what every iteration returned — one response
// from SORA per search. Totals here, details in the individual Send to SORA runs.

let accepted = 0, inserted = 0, duplicates = 0, rejected = 0, replayed = 0;

for (const item of $input.all()) {
  const j = item.json || {};
  accepted   += j.accepted   || 0;
  inserted   += j.inserted   || 0;
  duplicates += j.duplicates || 0;
  rejected   += Array.isArray(j.rejected) ? j.rejected.length : 0;
  if (j.replayed) replayed += 1;
}

return [{ json: { searches: $input.all().length, accepted, inserted, duplicates, rejected, replayed } }];
